def find_solutions(N):
    # c_i is the count of i in b.
    # sum_{i=1}^{N-1} i * c_i = N
    # sum_{i=1}^{N-1} c_i <= N
    # c_0 = N - sum_{i=1}^{N-1} c_i
    # a_i = count(c, i)
    # c_i = count(a, i)

    solutions = []

    # Using recursion to find all c
    def backtrack(i, current_sum_ic, current_sum_c, c):
        if i == N:
            if current_sum_ic == N and current_sum_c <= N:
                c0 = N - current_sum_c
                c[0] = c0
                # Check the condition
                a = [0] * N
                for v in range(N):
                    cnt = 0
                    for x in c:
                        if x == v:
                            cnt += 1
                    a[v] = cnt

                # Check if count(a, i) == c_i
                match = True
                for v in range(N):
                    cnt_a = 0
                    for x in a:
                        if x == v:
                            cnt_a += 1
                    if cnt_a != c[v]:
                        match = False
                        break
                if match:
                    solutions.append(list(a))
            return

        # Optimization:
        # i * c_i <= N - current_sum_ic
        # current_sum_c + c_i <= N

        max_c = N - current_sum_c
        if i > 0:
            max_c = min(max_c, (N - current_sum_ic) // i)

        for val in range(max_c + 1):
            if i > 0 and current_sum_ic + i * val > N:
                break
            c[i] = val
            backtrack(i + 1, current_sum_ic + i * val, current_sum_c + val, c)

    # Actually, let's use a different approach for finding c.
    # A partition of N can be represented by its parts.
    # For N=10, the number of partitions is 42.

    def get_all_partitions(n, min_val):
        if n == 0:
            yield []
            return
        for v in range(min_val, n + 1):
            for p in get_all_partitions(n - v, v):
                yield [v] + p

    for partition in get_all_partitions(N, 1):
        # partition is the list of non-zero elements in b.
        # So the elements of b are the elements of partition, plus some 0s.
        # But the number of elements in b is N.
        # So we have len(partition) non-zero elements, and N - len(partition) zeros.
        # This is only possible if len(partition) <= N.
        if len(partition) <= N:
            # Create c_i
            c = [0] * N
            for v in partition:
                if v < N:
                    c[v] += 1
            # The number of 0s in b is N - len(partition).
            # This is c_0. Wait, no.
            # b is the sequence. The number of 0s in b is c_0.
            # So c_0 = N - len(partition).
            c[0] = N - len(partition)
            # Now, we must also have sum c_i = N.
            # Sum c_i = c_0 + sum_{i=1}^{N-1} c_i = (N - len(partition)) + len(partition) = N.
            # This is always true.

def find_all_solutions(N):
    solutions = []

    def get_all_partitions(n, min_val):
        if n == 0:
            yield []
            return
        for v in range(min_val, n + 1):
            for p in get_all_partitions(n - v, v):
                yield [v] + p

    for partition in get_all_partitions(N, 1):
        if len(partition) <= N:
            c = [0] * N
            for v in partition:
                if v < N:
                    c[v] += 1
            c[0] = N - len(partition)

            a = [0] * N
            for v in range(N):
                cnt = 0
                for x in c:
                    if x == v:
                        cnt += 1
                a[v] = cnt

            match = True
            for v in range(N):
                cnt_a = 0
                for x in a:
                    if x == v:
                        cnt_a += 1
                if cnt_a != c[v]:
                    match = False
                    break
            if match:
                solutions.append(list(a))

    return solutions

for n in range(1, 13):
    sols = find_all_solutions(n)
    print(f"N={n}: {sols}")
